insert into public.courses (id, position, definition) values
    ('python', 10, '{"title":"Python Mastery","tagline":"From your first \"Hello World\" to shipping real Python projects.","level":"Beginner → Advanced","hours":30,"accent":"#3776AB","badge":"PY","requires":["python"],"capstone":{"title":"Command-line expense tracker","description":"A program you run in the terminal to record what you spend, see it by category, and keep it between runs.","requirements":["Add expenses (amount, category, note)","Delete expenses","List expenses and totals by category","Save data to a file","Read the data back when the program starts","Handle bad input and a missing or broken data file without crashing"]},"modules":[{"id":"getting-started","title":"Getting Started","description":"Set up Python the right way and understand what actually happens when your code runs.","lessons":[{"id":"what-is-python-and-what-can-you-build-with-it","title":"What is Python and what can you build with it"},{"id":"installing-python-3-on-your-machine","title":"Installing Python 3 on your machine"},{"id":"your-first-program-hello-world","title":"Your first program: Hello World","exercise":{"prompt":"Write a program that prints exactly `Hello, World!`","files":{"hello.py":"# Print Hello, World! below\n"},"check":{"type":"output","cases":[{"expected":"Hello, World!","match":"exact"}]},"hints":["`print()` shows whatever you put between its parentheses.","Text goes inside quotes, like `\"this\"`.","Match it exactly: a capital H, a comma, a space, a capital W and an exclamation mark."],"solution":"print(\"Hello, World!\")\n"}},{"id":"how-python-code-is-executed-interpreter-bytecode","title":"How Python code is executed (interpreter, bytecode)"},{"id":"setting-up-your-editor-and-python-extensions","title":"Setting up your editor and Python extensions"},{"id":"linting-and-formatting-with-pep-8","title":"Linting and formatting with PEP 8"},{"id":"running-scripts-vs-the-interactive-repl","title":"Running scripts vs the interactive REPL"},{"id":"comments-and-writing-readable-code","title":"Comments and writing readable code"}]},{"id":"primitive-types-and-variables","title":"Primitive Types & Variables","description":"Master the building blocks: variables, strings, and numbers.","lessons":[{"id":"variables-and-how-python-stores-them","title":"Variables and how Python stores them"},{"id":"variable-naming-conventions","title":"Variable naming conventions"},{"id":"strings-and-indexing-slicing","title":"Strings and indexing/slicing","exercise":{"prompt":"Finish `middle(word)` so it returns the word without its first and last letters. `middle(\"python\")` should return `\"ytho\"`.","files":{"middle.py":"def middle(word):\n    # Return word without its first and last characters\n    return word\n"},"check":{"type":"function","function":"middle","cases":[{"args":["python"],"expected":"ytho"},{"args":["cat"],"expected":"a"},{"args":["ab"],"expected":""}]},"hints":["A slice `word[start:end]` gives the characters from `start` up to, but not including, `end`.","Index 1 is the second character. A negative index counts from the end: -1 is the last character.","Start the slice at 1 and stop it at -1."],"solution":"def middle(word):\n    return word[1:-1]\n"}},{"id":"escape-sequences","title":"Escape sequences"},{"id":"formatted-strings-f-strings","title":"Formatted strings (f-strings)","exercise":{"prompt":"Finish `introduce(name, age)` so it returns a sentence like `\"Hi, I''m Ada and I''m 36 years old.\"` Use an f-string.","files":{"introduce.py":"def introduce(name, age):\n    # Return: Hi, I''m <name> and I''m <age> years old.\n    return \"Hi, I''m name and I''m age years old.\"\n"},"check":{"type":"function","function":"introduce","cases":[{"args":["Ada",36],"expected":"Hi, I''m Ada and I''m 36 years old."},{"args":["Linus",21],"expected":"Hi, I''m Linus and I''m 21 years old."}]},"hints":["An f-string starts with an `f` right before the opening quote: `f\"...\"`.","Inside an f-string, `{name}` is replaced by the value of the variable `name`.","Put `{name}` and `{age}` where the words name and age are now, and add the `f`."],"solution":"def introduce(name, age):\n    return f\"Hi, I''m {name} and I''m {age} years old.\"\n"}},{"id":"essential-string-methods","title":"Essential string methods","exercise":{"prompt":"Finish `clean_username(text)`: remove spaces at both ends, make it lowercase, and replace the spaces between words with underscores. `\"  Ada Lovelace \"` becomes `\"ada_lovelace\"`.","files":{"username.py":"def clean_username(text):\n    # 1. remove spaces at both ends  2. lowercase  3. spaces -> underscores\n    return text.lower()\n"},"check":{"type":"function","function":"clean_username","cases":[{"args":["  Ada Lovelace "],"expected":"ada_lovelace"},{"args":["GRACE"],"expected":"grace"},{"args":["Alan Mathison Turing"],"expected":"alan_mathison_turing"}]},"hints":["Strings have methods for each step: one removes whitespace at the ends, one lowercases, one replaces text.","They are `.strip()`, `.lower()` and `.replace(old, new)`.","Methods can be chained: `text.strip().lower().replace(\" \", \"_\")`."],"solution":"def clean_username(text):\n    return text.strip().lower().replace(\" \", \"_\")\n"}},{"id":"numbers-int-float-complex","title":"Numbers: int, float, complex"},{"id":"arithmetic-operators-and-augmented-assignment","title":"Arithmetic operators and augmented assignment","exercise":{"prompt":"Finish `minutes_and_seconds(total)` so it turns a number of seconds into minutes and the seconds left over. `minutes_and_seconds(125)` returns `(2, 5)`. Use `//` and `%`.","files":{"time_split.py":"def minutes_and_seconds(total):\n    minutes = total / 60\n    seconds = 0\n    return (minutes, seconds)\n"},"check":{"type":"function","function":"minutes_and_seconds","cases":[{"args":[125],"expected":[2,5]},{"args":[60],"expected":[1,0]},{"args":[59],"expected":[0,59]}]},"hints":["`/` always gives a float: `125 / 60` is `2.0833…`. You want the whole minutes only.","`//` divides and drops the remainder. `%` gives the remainder.","`minutes = total // 60` and `seconds = total % 60`."],"solution":"def minutes_and_seconds(total):\n    minutes = total // 60\n    seconds = total % 60\n    return (minutes, seconds)\n"}},{"id":"working-with-the-math-module","title":"Working with the math module"},{"id":"type-conversion-and-type","title":"Type conversion and type()","exercise":{"prompt":"This program should ask for two whole numbers and print their sum, but for 3 and 5 it prints `35`. `input()` always gives you text. Convert both answers to numbers so it prints `8`.","files":{"add.py":"a = input(\"First number: \")\nb = input(\"Second number: \")\nprint(a + b)\n"},"check":{"type":"output","cases":[{"name":"3 and 5 make 8","input":"3\n5","expected":"8","match":"contains"},{"name":"10 and 20 make 30","input":"10\n20","expected":"30","match":"contains"},{"name":"7 and 7 make 14","input":"7\n7","expected":"14","match":"contains"}]},"hints":["Adding two pieces of text joins them: `\"3\" + \"5\"` is `\"35\"`.","`int(\"3\")` turns the text `\"3\"` into the number `3`.","Wrap each `input(...)` in `int(...)`, or convert `a` and `b` before adding them."],"solution":"a = int(input(\"First number: \"))\nb = int(input(\"Second number: \"))\nprint(a + b)\n"}}]},{"id":"control-flow","title":"Control Flow","description":"Teach your programs to make decisions and repeat work.","lessons":[{"id":"comparison-operators","title":"Comparison operators"},{"id":"conditional-statements-if-elif-else","title":"Conditional statements (if / elif / else)","exercise":{"prompt":"Finish `grade(score)`: 90 and above is `\"A\"`, 80–89 `\"B\"`, 70–79 `\"C\"`, 60–69 `\"D\"`, and below 60 `\"F\"`.","files":{"grade.py":"def grade(score):\n    if score >= 90:\n        return \"A\"\n    # Add the other grades here\n"},"check":{"type":"function","function":"grade","cases":[{"args":[95],"expected":"A"},{"args":[90],"expected":"A"},{"args":[85],"expected":"B"},{"args":[72],"expected":"C"},{"args":[60],"expected":"D"},{"args":[59],"expected":"F"}]},"hints":["Add an `elif` for each grade, checking the highest scores first.","Once one condition is true, Python skips the rest, so `elif score >= 80` only runs for scores below 90.","Finish with `else: return \"F\"` for everything below 60."],"solution":"def grade(score):\n    if score >= 90:\n        return \"A\"\n    elif score >= 80:\n        return \"B\"\n    elif score >= 70:\n        return \"C\"\n    elif score >= 60:\n        return \"D\"\n    else:\n        return \"F\"\n"}},{"id":"ternary-conditional-expressions","title":"Ternary (conditional) expressions"},{"id":"logical-operators-and-or-not","title":"Logical operators (and / or / not)","exercise":{"prompt":"Finish `is_leap_year(year)`. A year is a leap year if it divides by 4, except years that divide by 100, unless they also divide by 400. So 2024 and 2000 are leap years; 2023 and 1900 are not.","files":{"leap.py":"def is_leap_year(year):\n    return year % 4 == 0\n"},"check":{"type":"function","function":"is_leap_year","cases":[{"args":[2024],"expected":true},{"args":[2023],"expected":false},{"args":[1900],"expected":false},{"args":[2000],"expected":true}]},"hints":["`year % 4 == 0` means \"divides by 4\". The same pattern works for 100 and 400.","Leap year = divides by 4 AND (does NOT divide by 100 OR divides by 400).","`return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)`"],"solution":"def is_leap_year(year):\n    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)\n"}},{"id":"short-circuit-evaluation","title":"Short-circuit evaluation"},{"id":"chaining-comparison-operators","title":"Chaining comparison operators"},{"id":"for-loops-and-range","title":"For loops and range()","exercise":{"prompt":"Finish `sum_up_to(n)` so it adds up every whole number from 1 to `n` with a `for` loop. `sum_up_to(5)` is 1 + 2 + 3 + 4 + 5 = `15`.","files":{"sum_up_to.py":"def sum_up_to(n):\n    total = 0\n    for number in range(1, n):\n        total += number\n    return total\n"},"check":{"type":"function","function":"sum_up_to","cases":[{"args":[1],"expected":1},{"args":[5],"expected":15},{"args":[100],"expected":5050},{"args":[0],"expected":0}]},"hints":["The loop is almost right. Print `list(range(1, 5))` to see which numbers it gives.","`range(start, stop)` stops just before `stop`.","Use `range(1, n + 1)` so `n` itself is included."],"solution":"def sum_up_to(n):\n    total = 0\n    for number in range(1, n + 1):\n        total += number\n    return total\n"}},{"id":"for-else","title":"for..else"},{"id":"nested-loops","title":"Nested loops"},{"id":"while-loops-and-infinite-loops","title":"While loops and infinite loops","exercise":{"prompt":"Finish `count_digits(n)` so it returns how many digits a non-negative whole number has, using a `while` loop. `count_digits(12345)` is `5` and `count_digits(0)` is `1`.","files":{"digits.py":"def count_digits(n):\n    # Hint: n // 10 drops the last digit\n    count = 0\n    return count\n"},"check":{"type":"function","function":"count_digits","cases":[{"args":[7],"expected":1},{"args":[42],"expected":2},{"args":[12345],"expected":5},{"args":[0],"expected":1}]},"hints":["Each time you do `n = n // 10`, the number loses one digit.","Every number has at least one digit, so start counting at 1.","Start with `count = 1`, then `while n >= 10:` divide `n` by 10 with `//` and add 1 to `count`."],"solution":"def count_digits(n):\n    count = 1\n    while n >= 10:\n        n = n // 10\n        count += 1\n    return count\n"}},{"id":"iterables-and-the-iteration-protocol","title":"Iterables and the iteration protocol"},{"id":"exercise-fizzbuzz-and-a-guessing-game","title":"Exercise: FizzBuzz and a guessing game","exercise":{"prompt":"Print the numbers from 1 to 15, one per line. For multiples of 3 print `Fizz` instead, for multiples of 5 print `Buzz`, and for multiples of both print `FizzBuzz`.","files":{"fizzbuzz.py":"for n in range(1, 16):\n    print(n)\n"},"check":{"type":"output","cases":[{"expected":"1\n2\nFizz\n4\nBuzz\nFizz\n7\n8\nFizz\nBuzz\n11\nFizz\n13\n14\nFizzBuzz","match":"exact"}]},"hints":["`n % 3 == 0` is true when `n` is a multiple of 3.","Check \"multiple of both\" first. Otherwise 15 would stop at the Fizz check.","Inside the loop: `if n % 15 == 0:` FizzBuzz, `elif n % 3 == 0:` Fizz, `elif n % 5 == 0:` Buzz, `else:` the number."],"solution":"for n in range(1, 16):\n    if n % 15 == 0:\n        print(\"FizzBuzz\")\n    elif n % 3 == 0:\n        print(\"Fizz\")\n    elif n % 5 == 0:\n        print(\"Buzz\")\n    else:\n        print(n)\n"}}]},{"id":"functions","title":"Functions","description":"Write reusable, clean functions like a professional.","lessons":[{"id":"defining-and-calling-functions","title":"Defining and calling functions"},{"id":"parameters-vs-arguments","title":"Parameters vs arguments"},{"id":"keyword-arguments","title":"Keyword arguments"},{"id":"default-argument-values","title":"Default argument values","exercise":{"prompt":"Change `power` so the exponent is optional and defaults to 2. `power(3)` should return `9`, and `power(2, 10)` should still return `1024`.","files":{"power.py":"def power(base, exponent):\n    return base ** exponent\n"},"check":{"type":"function","function":"power","cases":[{"args":[3],"expected":9},{"args":[2,10],"expected":1024},{"args":[5,0],"expected":1}]},"hints":["Right now `power(3)` fails because Python wants a value for every parameter.","A parameter can have a default value, used when the caller leaves it out.","Write `exponent=2` in the parameter list."],"solution":"def power(base, exponent=2):\n    return base ** exponent\n"}},{"id":"returning-values-and-returning-none","title":"Returning values (and returning None)","exercise":{"prompt":"Fix `average(numbers)` so it returns `None` for an empty list instead of crashing. `average([2, 4, 6])` is `4`.","files":{"average.py":"def average(numbers):\n    return sum(numbers) / len(numbers)\n"},"check":{"type":"function","function":"average","cases":[{"args":[[2,4,6]],"expected":4},{"args":[[1,2]],"expected":1.5},{"args":[[]],"expected":null}]},"hints":["For an empty list, `len(numbers)` is 0, and dividing by zero raises `ZeroDivisionError`.","An empty list counts as false, so `if not numbers:` is true only when it''s empty.","Before dividing: `if not numbers: return None`."],"solution":"def average(numbers):\n    if not numbers:\n        return None\n    return sum(numbers) / len(numbers)\n"}},{"id":"args-variable-length-arguments","title":"*args: variable-length arguments"},{"id":"kwargs-keyword-argument-packing","title":"**kwargs: keyword argument packing"},{"id":"scope-local-global-and-the-legb-rule","title":"Scope: local, global, and the LEGB rule"},{"id":"debugging-functions-step-by-step","title":"Debugging functions step by step"},{"id":"exercise-reusable-fibonacci-and-validation-helpers","title":"Exercise: reusable Fibonacci and validation helpers","exercise":{"prompt":"Finish `fibonacci(n)` so it returns a list of the first `n` Fibonacci numbers. The list starts `0, 1`, and each next number is the sum of the two before it: `fibonacci(7)` is `[0, 1, 1, 2, 3, 5, 8]`.","files":{"fibonacci.py":"def fibonacci(n):\n    numbers = []\n    # Build the list here\n    return numbers\n"},"check":{"type":"function","function":"fibonacci","cases":[{"args":[0],"expected":[]},{"args":[1],"expected":[0]},{"args":[2],"expected":[0,1]},{"args":[7],"expected":[0,1,1,2,3,5,8]}]},"hints":["Keep two variables for the last two numbers, starting at `a = 0` and `b = 1`.","Loop `n` times. Each time, add `a` to the list, then move forward one step.","Moving forward one step: `a, b = b, a + b`."],"solution":"def fibonacci(n):\n    numbers = []\n    a, b = 0, 1\n    for _ in range(n):\n        numbers.append(a)\n        a, b = b, a + b\n    return numbers\n"}}]},{"id":"data-structures","title":"Data Structures","description":"Lists, tuples, sets, and dictionaries — plus the idioms that make Python famous.","lessons":[{"id":"lists-creating-and-accessing-items","title":"Lists: creating and accessing items"},{"id":"list-unpacking","title":"List unpacking"},{"id":"adding-removing-and-finding-items","title":"Adding, removing, and finding items"},{"id":"sorting-lists-and-the-key-parameter","title":"Sorting lists and the key parameter"},{"id":"lambda-functions","title":"Lambda functions"},{"id":"map-and-filter","title":"Map and filter"},{"id":"list-comprehensions","title":"List comprehensions","exercise":{"prompt":"Finish `squares_of_evens(numbers)` with a list comprehension: return the square of every even number, in order. `squares_of_evens([1, 2, 3, 4])` is `[4, 16]`.","files":{"evens.py":"def squares_of_evens(numbers):\n    return [n for n in numbers]\n"},"check":{"type":"function","function":"squares_of_evens","cases":[{"args":[[1,2,3,4,5,6]],"expected":[4,16,36]},{"args":[[]],"expected":[]},{"args":[[7,9]],"expected":[]},{"args":[[-2,3]],"expected":[4]}]},"hints":["A list comprehension has the shape `[expression for item in items if condition]`.","The expression is what goes in the new list (the square); the condition picks which items to keep (the even ones).","`[n * n for n in numbers if n % 2 == 0]`"],"solution":"def squares_of_evens(numbers):\n    return [n * n for n in numbers if n % 2 == 0]\n"}},{"id":"zip","title":"Zip"},{"id":"stacks-and-queues-deque","title":"Stacks and queues (deque)"},{"id":"tuples-and-swapping-variables","title":"Tuples and swapping variables"},{"id":"sets-and-set-operations","title":"Sets and set operations"},{"id":"dictionaries-and-dictionary-comprehensions","title":"Dictionaries and dictionary comprehensions"},{"id":"generator-expressions","title":"Generator expressions"},{"id":"the-unpacking-operator-and","title":"The unpacking operator (* and **)"},{"id":"exercise-word-frequency-counter","title":"Exercise: word frequency counter","exercise":{"prompt":"Finish `word_counts(text)` so it returns a dictionary of how many times each word appears, ignoring upper and lower case. `word_counts(\"the cat the hat\")` is `{\"the\": 2, \"cat\": 1, \"hat\": 1}`.","files":{"words.py":"def word_counts(text):\n    counts = {}\n    # Count each word here\n    return counts\n"},"check":{"type":"function","function":"word_counts","cases":[{"args":["the cat the hat"],"expected":{"the":2,"cat":1,"hat":1}},{"args":["Go go GO"],"expected":{"go":3}},{"args":[""],"expected":{}}]},"hints":["`text.lower().split()` gives you a list of lowercase words.","Loop over the words. For each one, add 1 to its count in the dictionary.","`counts[word] = counts.get(word, 0) + 1`: `.get` returns 0 the first time a word is seen."],"solution":"def word_counts(text):\n    counts = {}\n    for word in text.lower().split():\n        counts[word] = counts.get(word, 0) + 1\n    return counts\n"}}]},{"id":"exceptions","title":"Exceptions","description":"Handle errors gracefully instead of crashing.","lessons":[{"id":"what-exceptions-are-and-reading-tracebacks","title":"What exceptions are and reading tracebacks"},{"id":"handling-exceptions-with-try-except","title":"Handling exceptions with try / except"},{"id":"handling-different-exception-types","title":"Handling different exception types"},{"id":"cleaning-up-with-finally","title":"Cleaning up with finally"},{"id":"the-with-statement-and-context-managers","title":"The with statement and context managers"},{"id":"raising-exceptions","title":"Raising exceptions"},{"id":"the-cost-of-raising-exceptions-eafp-vs-lbyl","title":"The cost of raising exceptions (EAFP vs LBYL)"}]},{"id":"classes-and-object-oriented-programming","title":"Classes & Object-Oriented Programming","description":"Model real-world concepts with classes, inheritance, and magic methods.","lessons":[{"id":"classes-vs-objects-instances","title":"Classes vs objects (instances)"},{"id":"creating-your-first-class","title":"Creating your first class"},{"id":"constructors-init","title":"Constructors (__init__)"},{"id":"instance-vs-class-attributes","title":"Instance vs class attributes"},{"id":"instance-class-and-static-methods","title":"Instance, class, and static methods"},{"id":"magic-methods-str-repr-eq","title":"Magic methods (__str__, __repr__, __eq__)"},{"id":"comparing-objects-and-arithmetic-operators","title":"Comparing objects and arithmetic operators"},{"id":"making-custom-containers","title":"Making custom containers"},{"id":"private-members-and-name-mangling","title":"Private members and name mangling"},{"id":"properties-property","title":"Properties (@property)"},{"id":"inheritance-and-method-overriding","title":"Inheritance and method overriding"},{"id":"multiple-inheritance-and-mro","title":"Multiple inheritance and MRO"},{"id":"abstract-base-classes","title":"Abstract base classes"},{"id":"duck-typing","title":"Duck typing"},{"id":"extending-built-in-types","title":"Extending built-in types"},{"id":"data-classes-dataclass","title":"Data classes (@dataclass)"}]},{"id":"modules-and-packages","title":"Modules & Packages","description":"Organize code across files and packages like real projects do.","lessons":[{"id":"creating-and-importing-modules","title":"Creating and importing modules"},{"id":"compiled-python-files-pycache","title":"Compiled Python files (__pycache__)"},{"id":"the-module-search-path","title":"The module search path"},{"id":"packages-and-init-py","title":"Packages and __init__.py"},{"id":"sub-packages","title":"Sub-packages"},{"id":"intra-package-references","title":"Intra-package references"},{"id":"the-dir-function","title":"The dir() function"},{"id":"executing-modules-as-scripts-name-main","title":"Executing modules as scripts (__name__ == \"__main__\")"}]},{"id":"the-standard-library","title":"The Standard Library","description":"The batteries included: files, dates, JSON, SQLite, and more.","lessons":[{"id":"working-with-paths-pathlib","title":"Working with paths (pathlib)"},{"id":"working-with-directories-and-files","title":"Working with directories and files"},{"id":"zip-files","title":"Zip files"},{"id":"csv-files","title":"CSV files"},{"id":"json","title":"JSON"},{"id":"sqlite-databases","title":"SQLite databases"},{"id":"timestamps-datetimes-and-time-deltas","title":"Timestamps, datetimes, and time deltas"},{"id":"generating-random-values","title":"Generating random values"},{"id":"command-line-arguments-sys-argv-argparse","title":"Command-line arguments (sys.argv, argparse)"},{"id":"running-external-programs-subprocess","title":"Running external programs (subprocess)"},{"id":"sending-emails-and-templates","title":"Sending emails and templates"}]},{"id":"pip-virtual-environments-and-packaging","title":"pip, Virtual Environments & Packaging","description":"Manage dependencies and share your code with the world.","lessons":[{"id":"the-python-package-index-pypi","title":"The Python Package Index (PyPI)"},{"id":"installing-packages-with-pip","title":"Installing packages with pip"},{"id":"virtual-environments-venv","title":"Virtual environments (venv)"},{"id":"managing-dependencies-requirements-txt","title":"Managing dependencies (requirements.txt)"},{"id":"project-layout-for-a-publishable-package","title":"Project layout for a publishable package"},{"id":"publishing-your-own-package","title":"Publishing your own package"},{"id":"docstrings-and-generating-docs-with-pydoc","title":"Docstrings and generating docs with pydoc"}]},{"id":"popular-libraries","title":"Popular Libraries","description":"A guided tour of the libraries professionals reach for daily.","lessons":[{"id":"calling-web-apis-with-requests","title":"Calling web APIs with requests"},{"id":"web-scraping-with-beautifulsoup","title":"Web scraping with BeautifulSoup"},{"id":"automating-excel-spreadsheets-openpyxl","title":"Automating Excel spreadsheets (openpyxl)"},{"id":"working-with-pdfs-and-images-pillow","title":"Working with PDFs and images (Pillow)"},{"id":"numpy-arrays-your-first-taste-of-data-science","title":"NumPy arrays: your first taste of data science"},{"id":"a-first-look-at-pandas-dataframes","title":"A first look at pandas DataFrames"}]},{"id":"capstone-project","title":"Capstone Project","description":"Put everything together: design, build, and package a complete CLI application.","lessons":[{"id":"choosing-and-scoping-the-project-expense-tracker-cli","title":"Choosing and scoping the project (expense tracker CLI)"},{"id":"designing-the-data-model-and-file-structure","title":"Designing the data model and file structure"},{"id":"building-the-core-features","title":"Building the core features"},{"id":"persisting-data-with-json-or-sqlite","title":"Persisting data with JSON or SQLite"},{"id":"handling-errors-and-edge-cases","title":"Handling errors and edge cases"},{"id":"writing-tests-with-pytest","title":"Writing tests with pytest"},{"id":"packaging-and-sharing-your-app","title":"Packaging and sharing your app"},{"id":"ideas-to-extend-it-further","title":"Ideas to extend it further"}]}]}'::jsonb),
    ('javascript', 20, '{"title":"JavaScript: The Complete Path","tagline":"The language of the web — from basics to async mastery.","level":"Beginner → Advanced","hours":35,"accent":"#F7DF1E","badge":"JS","requires":["node"],"capstone":{"title":"Weather app","description":"A small web app that looks up the weather for a city from a real weather API.","requirements":["Fetches data from a weather API","Search by city name","Shows a loading state while it waits","Handles errors: unknown city, no network, API failures","A clear, usable UI","Deployed somewhere, or with instructions to run it"],"achievementId":"api_builder"},"modules":[{"id":"getting-started","title":"Getting Started","description":"What JavaScript is, where it runs, and how to set up a professional workflow.","lessons":[{"id":"what-is-javascript-and-what-can-it-do","title":"What is JavaScript and what can it do"},{"id":"javascript-in-the-browser-vs-node-js","title":"JavaScript in the browser vs Node.js"},{"id":"setting-up-your-editor-and-dev-environment","title":"Setting up your editor and dev environment"},{"id":"your-first-script-and-the-browser-console","title":"Your first script and the browser console","exercise":{"prompt":"Write a script that logs exactly `Hello, World!` with `console.log()`.","files":{"hello.js":"// Log Hello, World! below\n"},"check":{"type":"output","cases":[{"expected":"Hello, World!","match":"exact"}]},"hints":["`console.log()` prints whatever you pass it.","Text is a string: put it in quotes, like `\"this\"`.","Match it exactly: a capital H, a comma, a space, a capital W and an exclamation mark."],"solution":"console.log(\"Hello, World!\");\n"}},{"id":"linking-scripts-to-html-and-separation-of-concerns","title":"Linking scripts to HTML and separation of concerns"},{"id":"statements-expressions-and-comments","title":"Statements, expressions, and comments"}]},{"id":"basics-variables-and-types","title":"Basics: Variables & Types","description":"The core value types and how JavaScript treats them.","lessons":[{"id":"variables-with-let-and-const-and-why-not-var","title":"Variables with let and const (and why not var)"},{"id":"primitive-types-string-number-boolean-undefined-null","title":"Primitive types: string, number, boolean, undefined, null"},{"id":"dynamic-typing-and-typeof","title":"Dynamic typing and typeof"},{"id":"objects-your-first-look","title":"Objects: your first look"},{"id":"arrays-your-first-look","title":"Arrays: your first look"},{"id":"functions-your-first-look","title":"Functions: your first look"},{"id":"template-literals","title":"Template literals","exercise":{"prompt":"Finish `greet(name, city)` with a template literal so it returns a string like `\"Hello, Ada from London!\"`.","files":{"greet.js":"function greet(name, city) {\n  return \"Hello, name from city!\";\n}\n"},"check":{"type":"function","function":"greet","cases":[{"args":["Ada","London"],"expected":"Hello, Ada from London!"},{"args":["Linus","Helsinki"],"expected":"Hello, Linus from Helsinki!"}]},"hints":["Template literals use backticks (`` ` ``) instead of quotes.","Inside backticks, `${name}` is replaced by the value of `name`.","Swap the quotes for backticks and write `${name}` and `${city}` where the words are."],"solution":"function greet(name, city) {\n  return `Hello, ${name} from ${city}!`;\n}\n"}}]},{"id":"operators","title":"Operators","description":"Every operator you will actually use, and the traps to avoid.","lessons":[{"id":"arithmetic-and-assignment-operators","title":"Arithmetic and assignment operators"},{"id":"comparison-operators","title":"Comparison operators"},{"id":"strict-equality-vs-loose-equality","title":"Strict equality (===) vs loose equality (==)"},{"id":"ternary-operator","title":"Ternary operator","exercise":{"prompt":"Finish `ticketPrice(age)` with the ternary operator: children under 12 pay `5`, everyone else pays `10`.","files":{"tickets.js":"function ticketPrice(age) {\n  // condition ? valueIfTrue : valueIfFalse\n  return 10;\n}\n"},"check":{"type":"function","function":"ticketPrice","cases":[{"args":[8],"expected":5},{"args":[11],"expected":5},{"args":[12],"expected":10},{"args":[40],"expected":10}]},"hints":["The ternary operator picks one of two values: `condition ? a : b`.","\"Under 12\" is `age < 12`. Exactly 12 pays the full price.","`return age < 12 ? 5 : 10;`"],"solution":"function ticketPrice(age) {\n  return age < 12 ? 5 : 10;\n}\n"}},{"id":"logical-operators-and-non-boolean-operands","title":"Logical operators and non-boolean operands"},{"id":"nullish-coalescing","title":"Nullish coalescing (??)","exercise":{"prompt":"Fix `displayName(user)` so it uses the nickname if there is one, then the name, then `\"Anonymous\"`. A nickname of `\"\"` counts as a nickname the user chose, so keep it. Only `null` and `undefined` should fall through.","files":{"display-name.js":"function displayName(user) {\n  return user.nickname || user.name || \"Anonymous\";\n}\n"},"check":{"type":"function","function":"displayName","cases":[{"name":"Uses the nickname","args":[{"name":"Ada","nickname":"Countess"}],"expected":"Countess"},{"name":"Falls back to the name","args":[{"name":"Linus","nickname":null}],"expected":"Linus"},{"name":"Keeps an empty nickname","args":[{"name":"Grace","nickname":""}],"expected":""},{"name":"Anonymous when nothing is set","args":[{}],"expected":"Anonymous"}]},"hints":["`||` skips every \"falsy\" value, and the empty string `\"\"` is falsy.","`??` only skips `null` and `undefined`.","Replace both `||` with `??`."],"solution":"function displayName(user) {\n  return user.nickname ?? user.name ?? \"Anonymous\";\n}\n"}},{"id":"operator-precedence","title":"Operator precedence"}]},{"id":"control-flow","title":"Control Flow","description":"Branching and looping through data.","lessons":[{"id":"if-else-and-else-if","title":"if...else and else if"},{"id":"switch-case","title":"switch...case","exercise":{"prompt":"Finish `dayName(day)` with a `switch`: 0 is `\"Sunday\"`, 1 `\"Monday\"`, … 6 `\"Saturday\"`. Any other number returns `\"Invalid day\"`.","files":{"days.js":"function dayName(day) {\n  switch (day) {\n    case 0:\n      return \"Sunday\";\n  }\n}\n"},"check":{"type":"function","function":"dayName","cases":[{"args":[0],"expected":"Sunday"},{"args":[1],"expected":"Monday"},{"args":[6],"expected":"Saturday"},{"args":[7],"expected":"Invalid day"}]},"hints":["Add one `case` per day, each with its own `return`.","Because each case returns, you don''t need `break` here.","`default: return \"Invalid day\";` handles every number without a case."],"solution":"function dayName(day) {\n  switch (day) {\n    case 0: return \"Sunday\";\n    case 1: return \"Monday\";\n    case 2: return \"Tuesday\";\n    case 3: return \"Wednesday\";\n    case 4: return \"Thursday\";\n    case 5: return \"Friday\";\n    case 6: return \"Saturday\";\n    default: return \"Invalid day\";\n  }\n}\n"}},{"id":"for-loops","title":"for loops","exercise":{"prompt":"Finish `sumArray(numbers)` so it adds up all the numbers in the array with a `for` loop. `sumArray([1, 2, 3])` is `6`, and an empty array sums to `0`.","files":{"sum.js":"function sumArray(numbers) {\n  let total = 0;\n  // Loop over numbers here\n  return total;\n}\n"},"check":{"type":"function","function":"sumArray","cases":[{"args":[[1,2,3]],"expected":6},{"args":[[10,-4]],"expected":6},{"args":[[]],"expected":0},{"args":[[0.5,0.25]],"expected":0.75}]},"hints":["A classic for loop: `for (let i = 0; i < numbers.length; i++) { ... }`.","Inside the loop, `numbers[i]` is the current number.","Add each one to the running total: `total += numbers[i];`"],"solution":"function sumArray(numbers) {\n  let total = 0;\n  for (let i = 0; i < numbers.length; i++) {\n    total += numbers[i];\n  }\n  return total;\n}\n"}},{"id":"while-and-do-while","title":"while and do...while"},{"id":"break-and-continue","title":"break and continue"},{"id":"for-in-vs-for-of","title":"for...in vs for...of"},{"id":"exercises-fizzbuzz-max-of-numbers-star-pattern","title":"Exercises: FizzBuzz, max of numbers, star pattern","exercise":{"prompt":"Finish `largest(numbers)` so it returns the biggest number in the array, without `Math.max`. Return `null` for an empty array.","files":{"largest.js":"function largest(numbers) {\n  let biggest = 0;\n  for (const n of numbers) {\n    if (n > biggest) biggest = n;\n  }\n  return biggest;\n}\n"},"check":{"type":"function","function":"largest","cases":[{"args":[[3,7,2]],"expected":7},{"name":"All negative numbers","args":[[-5,-1,-9]],"expected":-1},{"args":[[4]],"expected":4},{"name":"Empty array","args":[[]],"expected":null}]},"hints":["Try it with `[-5, -1, -9]`: starting at 0, no number is ever bigger than `biggest`.","Start with the first number of the array instead of 0.","Handle the empty array first (`if (numbers.length === 0) return null;`), then start with `let biggest = numbers[0];`."],"solution":"function largest(numbers) {\n  if (numbers.length === 0) return null;\n  let biggest = numbers[0];\n  for (const n of numbers) {\n    if (n > biggest) biggest = n;\n  }\n  return biggest;\n}\n"}}]},{"id":"objects","title":"Objects","description":"The heart of JavaScript: creating, cloning, and working with objects.","lessons":[{"id":"object-literals","title":"Object literals","exercise":{"prompt":"Finish `createAddress(street, city, zipCode)` so it returns an object with those three properties, like `{ street: \"1 Main St\", city: \"Springfield\", zipCode: \"12345\" }`.","files":{"address.js":"function createAddress(street, city, zipCode) {\n  return {};\n}\n"},"check":{"type":"function","function":"createAddress","cases":[{"args":["1 Main St","Springfield","12345"],"expected":{"street":"1 Main St","city":"Springfield","zipCode":"12345"}},{"args":["221B Baker St","London","NW1"],"expected":{"street":"221B Baker St","city":"London","zipCode":"NW1"}}]},"hints":["An object literal lists `key: value` pairs between braces.","The keys must be exactly `street`, `city` and `zipCode`.","When a variable has the same name as the key, you can write just the name: `{ street, city, zipCode }`."],"solution":"function createAddress(street, city, zipCode) {\n  return { street, city, zipCode };\n}\n"}},{"id":"factory-functions","title":"Factory functions"},{"id":"constructor-functions","title":"Constructor functions"},{"id":"dynamic-nature-of-objects","title":"Dynamic nature of objects"},{"id":"the-this-keyword-first-look","title":"The this keyword (first look)"},{"id":"cloning-objects-spread-object-assign","title":"Cloning objects (spread, Object.assign)"},{"id":"garbage-collection","title":"Garbage collection"},{"id":"built-ins-math-string-date","title":"Built-ins: Math, String, Date"},{"id":"exercise-address-and-blog-post-objects","title":"Exercise: address and blog post objects"}]},{"id":"arrays","title":"Arrays","description":"Every array method that matters, with real use cases.","lessons":[{"id":"adding-and-finding-elements","title":"Adding and finding elements"},{"id":"removing-elements-and-emptying-arrays","title":"Removing elements and emptying arrays"},{"id":"combining-and-slicing-arrays","title":"Combining and slicing arrays"},{"id":"the-spread-operator","title":"The spread operator"},{"id":"iterating-arrays","title":"Iterating arrays"},{"id":"joining-arrays-and-strings","title":"Joining arrays and strings"},{"id":"sorting-and-comparing","title":"Sorting and comparing"},{"id":"testing-elements-every-some","title":"Testing elements (every, some)"},{"id":"filtering-mapping-and-chaining","title":"Filtering, mapping, and chaining"},{"id":"reducing-an-array","title":"Reducing an array"},{"id":"exercise-array-utilities-from-scratch","title":"Exercise: array utilities from scratch"}]},{"id":"functions-in-depth","title":"Functions in Depth","description":"Closures, this, arrow functions — the topics interviews love.","lessons":[{"id":"function-declarations-vs-expressions","title":"Function declarations vs expressions"},{"id":"hoisting","title":"Hoisting"},{"id":"the-arguments-object-and-rest-parameters","title":"The arguments object and rest parameters"},{"id":"default-parameters","title":"Default parameters"},{"id":"getters-and-setters","title":"Getters and setters"},{"id":"local-vs-global-scope-let-vs-var","title":"Local vs global scope, let vs var"},{"id":"closures-explained","title":"Closures explained"},{"id":"the-this-keyword-in-depth","title":"The this keyword in depth"},{"id":"changing-this-call-apply-bind","title":"Changing this: call, apply, bind"},{"id":"arrow-functions-and-lexical-this","title":"Arrow functions and lexical this"}]},{"id":"object-oriented-javascript-and-prototypes","title":"Object-Oriented JavaScript & Prototypes","description":"How inheritance really works under the hood, then the ES6 class syntax.","lessons":[{"id":"the-four-pillars-of-oop","title":"The four pillars of OOP"},{"id":"prototypes-and-prototypical-inheritance","title":"Prototypes and prototypical inheritance"},{"id":"prototype-vs-instance-members","title":"Prototype vs instance members"},{"id":"property-descriptors","title":"Property descriptors"},{"id":"es6-classes","title":"ES6 classes"},{"id":"static-methods","title":"Static methods"},{"id":"private-members-fields-symbols-weakmaps","title":"Private members (# fields, symbols, WeakMaps)"},{"id":"getters-and-setters-in-classes","title":"Getters and setters in classes"},{"id":"inheritance-and-method-overriding","title":"Inheritance and method overriding"},{"id":"polymorphism","title":"Polymorphism"},{"id":"composition-over-inheritance-mixins","title":"Composition over inheritance (mixins)"},{"id":"exercise-building-a-stack-class","title":"Exercise: building a Stack class"}]},{"id":"modern-javascript-es6","title":"Modern JavaScript (ES6+)","description":"The modern syntax and features every codebase uses today.","lessons":[{"id":"modules-import-and-export","title":"Modules: import and export"},{"id":"commonjs-vs-es-modules","title":"CommonJS vs ES Modules"},{"id":"destructuring-objects-and-arrays","title":"Destructuring objects and arrays"},{"id":"optional-chaining","title":"Optional chaining (?.)"},{"id":"symbols","title":"Symbols"},{"id":"iterators-and-generators","title":"Iterators and generators"},{"id":"map-and-set","title":"Map and Set"},{"id":"tagged-templates","title":"Tagged templates"},{"id":"transpiling-and-bundling-overview-babel-vite","title":"Transpiling and bundling overview (Babel, Vite)"}]},{"id":"asynchronous-javascript","title":"Asynchronous JavaScript","description":"The event loop, promises, and async/await — demystified.","lessons":[{"id":"synchronous-vs-asynchronous-code","title":"Synchronous vs asynchronous code"},{"id":"the-event-loop-and-callback-queue","title":"The event loop and callback queue"},{"id":"callbacks-and-callback-hell","title":"Callbacks and callback hell"},{"id":"promises-consuming-and-creating","title":"Promises: consuming and creating"},{"id":"chaining-promises","title":"Chaining promises"},{"id":"promise-all-allsettled-race","title":"Promise.all, allSettled, race"},{"id":"async-await","title":"async / await"},{"id":"error-handling-in-async-code","title":"Error handling in async code"},{"id":"exercise-converting-callback-code-to-async-await","title":"Exercise: converting callback code to async/await"}]},{"id":"the-dom-and-events","title":"The DOM & Events","description":"Make web pages interactive: select, modify, and react to the page.","lessons":[{"id":"the-dom-tree","title":"The DOM tree"},{"id":"selecting-elements-queryselector-and-friends","title":"Selecting elements (querySelector and friends)"},{"id":"changing-content-attributes-and-styles","title":"Changing content, attributes, and styles"},{"id":"creating-and-removing-elements","title":"Creating and removing elements"},{"id":"events-and-addeventlistener","title":"Events and addEventListener"},{"id":"the-event-object","title":"The event object"},{"id":"event-bubbling-and-delegation","title":"Event bubbling and delegation"},{"id":"working-with-forms","title":"Working with forms"},{"id":"fetching-data-with-fetch","title":"Fetching data with fetch()"},{"id":"project-dynamic-search-and-filter-list","title":"Project: dynamic search-and-filter list"}]},{"id":"error-handling-and-debugging","title":"Error Handling & Debugging","description":"Find and fix bugs like a professional.","lessons":[{"id":"error-types-and-reading-stack-traces","title":"Error types and reading stack traces"},{"id":"try-catch-finally-and-throwing-errors","title":"try / catch / finally and throwing errors"},{"id":"custom-error-classes","title":"Custom error classes"},{"id":"debugging-with-breakpoints-in-devtools","title":"Debugging with breakpoints in DevTools"},{"id":"console-beyond-console-log","title":"console beyond console.log"},{"id":"defensive-programming-patterns","title":"Defensive programming patterns"}]},{"id":"capstone-project","title":"Capstone Project","description":"Build a complete interactive browser app from scratch.","lessons":[{"id":"scoping-the-project-quiz-game-or-expense-tracker","title":"Scoping the project (quiz game or expense tracker)"},{"id":"structuring-modules-and-state","title":"Structuring modules and state"},{"id":"building-the-ui-and-rendering-logic","title":"Building the UI and rendering logic"},{"id":"handling-user-events-and-validation","title":"Handling user events and validation"},{"id":"persisting-with-localstorage","title":"Persisting with localStorage"},{"id":"fetching-from-a-public-api","title":"Fetching from a public API"},{"id":"polish-refactor-and-deploy","title":"Polish, refactor, and deploy"}]}]}'::jsonb),
    ('typescript', 30, '{"title":"TypeScript Mastery","tagline":"Level up your JavaScript with static types, generics, and pro tooling.","level":"Intermediate (JavaScript required)","hours":20,"accent":"#3178C6","badge":"TS","requires":["node"],"modules":[{"id":"getting-started","title":"Getting Started","description":"Why TypeScript exists and how to set up the compiler properly.","lessons":[{"id":"what-is-typescript-and-why-use-it","title":"What is TypeScript and why use it"},{"id":"installing-the-typescript-compiler","title":"Installing the TypeScript compiler"},{"id":"your-first-typescript-program","title":"Your first TypeScript program"},{"id":"configuring-tsconfig-json-the-options-that-matter","title":"Configuring tsconfig.json (the options that matter)"},{"id":"compiling-and-running","title":"Compiling and running"},{"id":"debugging-with-source-maps","title":"Debugging with source maps"}]},{"id":"fundamentals","title":"Fundamentals","description":"The built-in types and how annotation and inference work together.","lessons":[{"id":"type-annotations-vs-type-inference","title":"Type annotations vs type inference"},{"id":"built-in-types-number-string-boolean","title":"Built-in types: number, string, boolean"},{"id":"the-any-type-and-why-to-avoid-it","title":"The any type (and why to avoid it)"},{"id":"arrays","title":"Arrays"},{"id":"tuples","title":"Tuples"},{"id":"enums-and-const-enums","title":"Enums (and const enums)"},{"id":"typing-functions-parameters-and-return-types","title":"Typing functions: parameters and return types"},{"id":"typing-objects","title":"Typing objects"}]},{"id":"advanced-types","title":"Advanced Types","description":"Unions, intersections, literals — the types that model real data.","lessons":[{"id":"type-aliases","title":"Type aliases"},{"id":"union-types","title":"Union types"},{"id":"intersection-types","title":"Intersection types"},{"id":"literal-types","title":"Literal types"},{"id":"nullable-types-and-strictnullchecks","title":"Nullable types and strictNullChecks"},{"id":"optional-chaining-and-nullish-coalescing-with-types","title":"Optional chaining and nullish coalescing with types"},{"id":"type-assertions-as","title":"Type assertions (as)"},{"id":"unknown-vs-any","title":"unknown vs any"},{"id":"the-never-type","title":"The never type"}]},{"id":"type-narrowing","title":"Type Narrowing","description":"Teach the compiler what you already know about your values.","lessons":[{"id":"typeof-and-truthiness-narrowing","title":"typeof and truthiness narrowing"},{"id":"instanceof-and-in-narrowing","title":"instanceof and in narrowing"},{"id":"equality-narrowing","title":"Equality narrowing"},{"id":"discriminated-unions","title":"Discriminated unions"},{"id":"type-predicates-is","title":"Type predicates (is)"},{"id":"exhaustiveness-checking-with-never","title":"Exhaustiveness checking with never"}]},{"id":"object-oriented-typescript","title":"Object-Oriented TypeScript","description":"Classes and interfaces with full compile-time safety.","lessons":[{"id":"classes-and-constructors","title":"Classes and constructors"},{"id":"access-modifiers-public-private-protected","title":"Access modifiers: public, private, protected"},{"id":"parameter-properties","title":"Parameter properties"},{"id":"readonly-and-optional-properties","title":"Readonly and optional properties"},{"id":"getters-and-setters","title":"Getters and setters"},{"id":"index-signatures","title":"Index signatures"},{"id":"static-members","title":"Static members"},{"id":"inheritance-and-method-overriding","title":"Inheritance and method overriding"},{"id":"polymorphism-and-the-open-closed-principle","title":"Polymorphism and the open-closed principle"},{"id":"abstract-classes","title":"Abstract classes"},{"id":"interfaces-vs-type-aliases","title":"Interfaces vs type aliases"},{"id":"implementing-interfaces","title":"Implementing interfaces"}]},{"id":"generics","title":"Generics","description":"Write flexible, reusable code without giving up type safety.","lessons":[{"id":"why-generics-exist","title":"Why generics exist"},{"id":"generic-functions","title":"Generic functions"},{"id":"generic-classes","title":"Generic classes"},{"id":"generic-interfaces","title":"Generic interfaces"},{"id":"generic-constraints-extends","title":"Generic constraints (extends)"},{"id":"extending-generic-classes","title":"Extending generic classes"},{"id":"the-keyof-operator","title":"The keyof operator"},{"id":"mapped-types","title":"Mapped types"}]},{"id":"utility-and-conditional-types","title":"Utility & Conditional Types","description":"The type-level toolbox: transform types instead of rewriting them.","lessons":[{"id":"partial-required-and-readonly","title":"Partial, Required, and Readonly"},{"id":"pick-omit-and-record","title":"Pick, Omit, and Record"},{"id":"returntype-parameters-and-awaited","title":"ReturnType, Parameters, and Awaited"},{"id":"template-literal-types","title":"Template literal types"},{"id":"conditional-types","title":"Conditional types"},{"id":"infer","title":"infer"}]},{"id":"decorators","title":"Decorators","description":"Meta-programming for classes — the feature behind Angular and NestJS.","lessons":[{"id":"what-decorators-are-and-enabling-them","title":"What decorators are and enabling them"},{"id":"class-decorators","title":"Class decorators"},{"id":"method-decorators","title":"Method decorators"},{"id":"accessor-and-property-decorators","title":"Accessor and property decorators"},{"id":"parameter-decorators","title":"Parameter decorators"},{"id":"decorator-factories-and-composition","title":"Decorator factories and composition"}]},{"id":"modules-and-project-structure","title":"Modules & Project Structure","description":"Organizing real TypeScript codebases.","lessons":[{"id":"exporting-and-importing","title":"Exporting and importing"},{"id":"default-exports-and-re-exports","title":"Default exports and re-exports"},{"id":"module-resolution-explained","title":"Module resolution explained"},{"id":"namespaces-and-why-modules-won","title":"Namespaces (and why modules won)"},{"id":"path-aliases","title":"Path aliases"},{"id":"declaration-merging-basics","title":"Declaration merging basics"}]},{"id":"integrating-with-javascript","title":"Integrating with JavaScript","description":"Adopt TypeScript gradually in existing JS projects.","lessons":[{"id":"including-js-code-with-allowjs","title":"Including JS code with allowJs"},{"id":"type-checking-js-with-checkjs-and-ts-check","title":"Type checking JS with checkJs and @ts-check"},{"id":"describing-types-with-jsdoc","title":"Describing types with JSDoc"},{"id":"declaration-files-d-ts","title":"Declaration files (.d.ts)"},{"id":"using-types-definitelytyped-packages","title":"Using @types / DefinitelyTyped packages"},{"id":"migration-strategy-for-a-real-project","title":"Migration strategy for a real project"}]},{"id":"tooling-and-quality","title":"Tooling & Quality","description":"The professional TypeScript toolchain.","lessons":[{"id":"eslint-with-typescript-eslint","title":"ESLint with typescript-eslint"},{"id":"formatting-with-prettier","title":"Formatting with Prettier"},{"id":"running-ts-directly-tsx-ts-node","title":"Running TS directly (tsx, ts-node)"},{"id":"building-with-vite-esbuild","title":"Building with Vite / esbuild"},{"id":"testing-typed-code-vitest-jest","title":"Testing typed code (Vitest / Jest)"},{"id":"publishing-a-typed-npm-package","title":"Publishing a typed npm package"}]},{"id":"typescript-in-the-real-world-capstone","title":"TypeScript in the Real World + Capstone","description":"Framework patterns, then build a fully typed project.","lessons":[{"id":"typing-react-components-and-hooks","title":"Typing React components and hooks"},{"id":"typing-node-js-express-apis","title":"Typing Node.js / Express APIs"},{"id":"zod-and-runtime-validation-meets-static-types","title":"Zod and runtime validation meets static types"},{"id":"capstone-design-a-typed-rest-api","title":"Capstone: design a typed